package com.univmar.admin.api;
import com.univmar.admin.AdminService; import jakarta.validation.Valid; import java.util.List; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController {private final AdminService service;public AdminController(AdminService service){this.service=service;}@GetMapping("/users") public List<AdminDtos.UserResponse> users(){return service.users();}@PatchMapping("/users/{id}") public AdminDtos.UserResponse update(@PathVariable Long id,@Valid @RequestBody AdminDtos.UserUpdate input){return service.updateUser(id,input);}@GetMapping("/audit/{entityType}/{entityId}") public List<AdminDtos.AuditResponse> audit(@PathVariable String entityType,@PathVariable Long entityId){return service.audit(entityType,entityId);}}
